class HydrationCssVarResolver {
  expectedMap: Map<string, string>
  policy: CssVarNamePolicy

  constructor(
    expectedMap: Map<string, string>,
    policy = CssVarNamePolicy.standard(),
  ) {
    this.expectedMap = expectedMap
    this.policy = policy
  }

  resolveCssVars(frame: ComponentCssVarFrame, vnode: VNode): void {
    const root = frame.subTree
    if (
      frame.cssVarsGetter &&
      (vnode === root ||
        (root &&
          frame.rootType === Fragment &&
          (frame.rootChildren as VNode[]).includes(vnode)))
    ) {
      const cssVars = frame.cssVarsGetter()
      for (const key in cssVars) {
        this.expectedMap.set(
          `${this.policy.prefix}${this.policy.escape(key)}`,
          String(cssVars[key]),
        )
      }
    }
    if (vnode === root && frame.parent) {
      this.resolveCssVars(ComponentCssVarFrame.from(frame.parent), frame.vnode)
    }
  }
}

